let sum=0;
function show(){
  game.say('当前合计 '+sum+'/4，目标 4/4');
  game.draw([
    ['text',sum+'/4',38,40,9,'#276B91'],
    ['text','目标 4/4',34,56,5,'#555555']
  ]);
}
game.buttons([
  {id:'1',label:'加1/4'},
  {id:'2',label:'加2/4'},
  {id:'3',label:'加3/4'},
  {id:'reset',label:'清空'}
]);
game.onAction(id=>{
  if(id==='reset'){sum=0;show();return;}
  sum+=Number(id);
  show();
  if(sum===4){
    game.finish('4/4 就是 1：同分母相加，分子相加，分子等于分母时和为1。');
  }else if(sum>4){
    game.say('超过1了，多出 '+(sum-4)+'/4。清空后换一组更小的块。');
  }
});
show();
